1	// Port of PyYAML's serializer.py.
2	//
3	// Composition note: PyYAML's `Serializer.__init__` takes keyword arguments that
4	// `Dumper.__init__` forwards. Here the mixin constructor receives whatever
5	// `new Dumper(stream, options)` was called with; the options bag is the first
6	// object-valued argument after the stream.
7	
8	import { SerializerError } from './errors.mjs';
9	import {
10	  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
11	  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
12	  MappingStartEvent, MappingEndEvent,
13	} from './events.mjs';
14	import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
15	
16	function dumperOptions(args) {
17	  for (let i = 1; i < args.length; i++) {
18	    if (args[i] !== null && typeof args[i] === 'object') return args[i];
19	  }
20	  return {};
21	}
22	
23	/** Python's `'id%03d' % n`. */
24	function formatAnchor(template, n) {
25	  const at = template.indexOf('%03d');
26	  if (at < 0) return template;
27	  let digits = String(n);
28	  while (digits.length < 3) digits = '0' + digits;
29	  return template.slice(0, at) + digits + template.slice(at + 4);
30	}
31	
32	export const SerializerMixin = (Base) => {
33	  class Serializer extends Base {
34	    constructor(...args) {
35	      super(...args);
36	      const options = dumperOptions(args);
37	      this.useEncoding = options.encoding ?? null;
38	      this.useExplicitStart = options.explicitStart ?? null;
39	      this.useExplicitEnd = options.explicitEnd ?? null;
40	      this.useVersion = options.version ?? null;
41	      this.useTags = options.tags ?? null;
42	      // Python dicts keyed by node identity -> JS Maps keyed by the node object.
43	      this.serializedNodes = new Map();
44	      this.anchors = new Map();
45	      this.lastAnchorId = 0;
46	      this.closed = null;
47	    }
48	
49	    open() {
50	      if (this.closed === null) {
51	        this.emit(new StreamStartEvent(null, null, this.useEncoding));
52	        this.closed = false;
53	      } else if (this.closed) {
54	        throw new SerializerError('serializer is closed');
55	      } else {
56	        throw new SerializerError('serializer is already opened');
57	      }
58	    }
59	
60	    close() {
61	      if (this.closed === null) {
62	        throw new SerializerError('serializer is not opened');
63	      } else if (!this.closed) {
64	        this.emit(new StreamEndEvent());
65	        this.closed = true;
66	      }
67	    }
68	
69	    serialize(node) {
70	      if (this.closed === null) {
71	        throw new SerializerError('serializer is not opened');
72	      } else if (this.closed) {
73	        throw new SerializerError('serializer is closed');
74	      }
75	      this.emit(new DocumentStartEvent(
76	        null, null, this.useExplicitStart, this.useVersion, this.useTags));
77	      this.anchorNode(node);
78	      this.serializeNode(node, null, null);
79	      this.emit(new DocumentEndEvent(null, null, this.useExplicitEnd));
80	      this.serializedNodes = new Map();
81	      this.anchors = new Map();
82	      this.lastAnchorId = 0;
83	    }
84	
85	    // Two passes in one walk: a node is entered with a null anchor, and only
86	    // earns a generated anchor when it is reached a second time. Anchor ids are
87	    // therefore handed out in *second*-encounter order.
88	    anchorNode(node) {
89	      if (this.anchors.has(node)) {
90	        if (this.anchors.get(node) === null) {
91	          this.anchors.set(node, this.generateAnchor(node));
92	        }
93	      } else {
94	        this.anchors.set(node, null);
95	        if (node instanceof SequenceNode) {
96	          for (const item of node.value) this.anchorNode(item);
97	        } else if (node instanceof MappingNode) {
98	          for (const [key, value] of node.value) {
99	            this.anchorNode(key);
100	            this.anchorNode(value);
101	          }
102	        }
103	      }
104	    }
105	
106	    generateAnchor(node) { // eslint-disable-line no-unused-vars
107	      this.lastAnchorId += 1;
108	      return formatAnchor(this.ANCHOR_TEMPLATE, this.lastAnchorId);
109	    }
110	
111	    serializeNode(node, parent, index) {
112	      const alias = this.anchors.get(node);
113	      if (this.serializedNodes.has(node)) {
114	        this.emit(new AliasEvent(alias));
115	      } else {
116	        this.serializedNodes.set(node, true);
117	        this.descendResolver(parent, index);
118	        if (node instanceof ScalarNode) {
119	          const detectedTag = this.resolve(ScalarNode, node.value, [true, false]);
120	          const defaultTag = this.resolve(ScalarNode, node.value, [false, true]);
121	          const implicit = [node.tag === detectedTag, node.tag === defaultTag];
122	          this.emit(new ScalarEvent(
123	            alias, node.tag, implicit, node.value, null, null, node.style));
124	        } else if (node instanceof SequenceNode) {
125	          const implicit = node.tag === this.resolve(SequenceNode, node.value, true);
126	          this.emit(new SequenceStartEvent(
127	            alias, node.tag, implicit, null, null, node.flowStyle));
128	          let i = 0;
129	          for (const item of node.value) {
130	            this.serializeNode(item, node, i);
131	            i += 1;
132	          }
133	          this.emit(new SequenceEndEvent());
134	        } else if (node instanceof MappingNode) {
135	          const implicit = node.tag === this.resolve(MappingNode, node.value, true);
136	          this.emit(new MappingStartEvent(
137	            alias, node.tag, implicit, null, null, node.flowStyle));
138	          for (const [key, value] of node.value) {
139	            this.serializeNode(key, node, null);
140	            this.serializeNode(value, node, key);
141	          }
142	          this.emit(new MappingEndEvent());
143	        }
144	        this.ascendResolver();
145	      }
146	    }
147	  }
148	
149	  Serializer.prototype.ANCHOR_TEMPLATE = 'id%03d';
150	  return Serializer;
151	};
