1	// Port of PyYAML's representer.py — BaseRepresenter, SafeRepresenter and the
2	// extra Representer entries that the full Dumper adds (notably python/tuple).
3	//
4	// PyYAML dispatches on `type(data).__mro__` against class-level dicts. Here the
5	// registries are module-level Maps keyed by the Python type *name* that
6	// `pyTypeName` reports, and `pyMro` supplies the (short) method resolution
7	// orders that matter: bool -> int, datetime -> date.
8	//
9	// `id(data)` becomes the data object itself: a JS Map keys on object identity,
10	// which is exactly what CPython's id() based alias key gives us.
11	
12	import { RepresenterError, PyTypeError } from './errors.mjs';
13	import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
14	import {
15	  PyBytes, PyTuple, PyDict, PySet,
16	  pyTypeName, pyReprFloat, pyLessThan, pySortInPlace, encodeBase64Wrapped,
17	} from './pytypes.mjs';
18	
19	const yamlRepresenters = new Map();
20	const yamlMultiRepresenters = new Map();
21	
22	function addRepresenter(dataType, representer) {
23	  yamlRepresenters.set(dataType, representer);
24	}
25	
26	function addMultiRepresenter(dataType, representer) {
27	  yamlMultiRepresenters.set(dataType, representer);
28	}
29	
30	/** The prefix of `type(data).__mro__` that the registries can match on. */
31	function pyMro(data) {
32	  const name = pyTypeName(data);
33	  if (name === 'bool') return ['bool', 'int', 'object'];
34	  if (name === 'datetime') return ['datetime', 'date', 'object'];
35	  return [name, 'object'];
36	}
37	
38	/** Python `for item in sequence` over the sequence types we can be handed. */
39	function iterate(sequence) {
40	  if (sequence instanceof PyTuple) return sequence.items;
41	  if (sequence instanceof PySet) return sequence.values();
42	  return sequence;
43	}
44	
45	/** Python `hasattr(mapping, 'items')`. */
46	function hasItems(mapping) {
47	  return mapping !== null && typeof mapping === 'object' &&
48	    typeof mapping.items === 'function';
49	}
50	
51	function dumperOptions(args) {
52	  for (let i = 1; i < args.length; i++) {
53	    if (args[i] !== null && typeof args[i] === 'object') return args[i];
54	  }
55	  return {};
56	}
57	
58	export const RepresenterMixin = (Base) => {
59	  class Representer extends Base {
60	    constructor(...args) {
61	      super(...args);
62	      const options = dumperOptions(args);
63	      this.defaultStyle = options.defaultStyle ?? null;
64	      this.sortKeys = options.sortKeys ?? true;
65	      this.defaultFlowStyle = options.defaultFlowStyle ?? false;
66	      this.representedObjects = new Map();
67	      this.objectKeeper = [];
68	      this.aliasKey = null;
69	    }
70	
71	    // ---------------------------------------------------------------- Base
72	
73	    represent(data) {
74	      const node = this.representData(data);
75	      this.serialize(node);
76	      this.representedObjects = new Map();
77	      this.objectKeeper = [];
78	      this.aliasKey = null;
79	    }
80	
81	    representData(data) {
82	      if (this.ignoreAliases(data)) this.aliasKey = null;
83	      else this.aliasKey = data;
84	      if (this.aliasKey !== null) {
85	        if (this.representedObjects.has(this.aliasKey)) {
86	          return this.representedObjects.get(this.aliasKey);
87	        }
88	        this.objectKeeper.push(data);
89	      }
90	      const dataTypes = pyMro(data);
91	      let node;
92	      if (this.yamlRepresenters.has(dataTypes[0])) {
93	        node = this.yamlRepresenters.get(dataTypes[0])(this, data);
94	      } else {
95	        let matched = false;
96	        for (const dataType of dataTypes) {
97	          if (this.yamlMultiRepresenters.has(dataType)) {
98	            node = this.yamlMultiRepresenters.get(dataType)(this, data);
99	            matched = true;
100	            break;
101	          }
102	        }
103	        if (!matched) {
104	          if (this.yamlMultiRepresenters.has(null)) {
105	            node = this.yamlMultiRepresenters.get(null)(this, data);
106	          } else if (this.yamlRepresenters.has(null)) {
107	            node = this.yamlRepresenters.get(null)(this, data);
108	          } else {
109	            node = new ScalarNode(null, String(data));
110	          }
111	        }
112	      }
113	      return node;
114	    }
115	
116	    representKey(data) {
117	      return this.representData(data);
118	    }
119	
120	    representScalar(tag, value, style = null) {
121	      if (style === null) style = this.defaultStyle;
122	      const node = new ScalarNode(tag, value, null, null, style);
123	      if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
124	      return node;
125	    }
126	
127	    representSequence(tag, sequence, flowStyle = null) {
128	      const value = [];
129	      const node = new SequenceNode(tag, value, null, null, flowStyle);
130	      if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
131	      let bestStyle = true;
132	      for (const item of iterate(sequence)) {
133	        const nodeItem = this.representData(item);
134	        if (!(nodeItem instanceof ScalarNode && !nodeItem.style)) bestStyle = false;
135	        value.push(nodeItem);
136	      }
137	      if (flowStyle === null) {
138	        if (this.defaultFlowStyle !== null) node.flowStyle = this.defaultFlowStyle;
139	        else node.flowStyle = bestStyle;
140	      }
141	      return node;
142	    }
143	
144	    representMapping(tag, mapping, flowStyle = null) {
145	      const value = [];
146	      const node = new MappingNode(tag, value, null, null, flowStyle);
147	      if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
148	      let bestStyle = true;
149	      if (hasItems(mapping)) {
150	        mapping = mapping.items();
151	        if (this.sortKeys) {
152	          // `mapping = sorted(mapping)` — sorted() builds a new list, so a
153	          // TypeError from any single comparison leaves the insertion order
154	          // untouched. Hence the sort happens on a copy.
155	          try {
156	            const ordered = mapping.slice();
157	            pySortInPlace(ordered, (a, b) => pyLessThan(a, b));
158	            mapping = ordered;
159	          } catch (err) {
160	            if (!(err instanceof PyTypeError)) throw err;
161	          }
162	        }
163	      }
164	      for (const [itemKey, itemValue] of mapping) {
165	        const nodeKey = this.representKey(itemKey);
166	        const nodeValue = this.representData(itemValue);
167	        if (!(nodeKey instanceof ScalarNode && !nodeKey.style)) bestStyle = false;
168	        if (!(nodeValue instanceof ScalarNode && !nodeValue.style)) bestStyle = false;
169	        value.push([nodeKey, nodeValue]);
170	      }
171	      if (flowStyle === null) {
172	        if (this.defaultFlowStyle !== null) node.flowStyle = this.defaultFlowStyle;
173	        else node.flowStyle = bestStyle;
174	      }
175	      return node;
176	    }
177	
178	    // ---------------------------------------------------------------- Safe
179	
180	    ignoreAliases(data) {
181	      if (data === null) return true;
182	      if (data instanceof PyTuple && data.items.length === 0) return true;
183	      if (typeof data === 'string' || data instanceof PyBytes ||
184	        typeof data === 'boolean' || typeof data === 'bigint' ||
185	        typeof data === 'number') return true;
186	      // falls off the end -> None, which is falsy, as in PyYAML
187	    }
188	
189	    representNone(data) {
190	      return this.representScalar('tag:yaml.org,2002:null', 'null');
191	    }
192	
193	    representStr(data) {
194	      return this.representScalar('tag:yaml.org,2002:str', data);
195	    }
196	
197	    representBinary(data) {
198	      const text = encodeBase64Wrapped(data.bytes);
199	      return this.representScalar('tag:yaml.org,2002:binary', text, '|');
200	    }
201	
202	    representBool(data) {
203	      const value = data ? 'true' : 'false';
204	      return this.representScalar('tag:yaml.org,2002:bool', value);
205	    }
206	
207	    representInt(data) {
208	      return this.representScalar('tag:yaml.org,2002:int', data.toString());
209	    }
210	
211	    representFloat(data) {
212	      let value;
213	      if (data !== data) {
214	        value = '.nan';
215	      } else if (data === Infinity) {
216	        value = '.inf';
217	      } else if (data === -Infinity) {
218	        value = '-.inf';
219	      } else {
220	        value = pyReprFloat(data).toLowerCase();
221	        // repr() can drop the fractional part (repr(1e17) == '1e+17'), which is
222	        // not a valid !!float; put '.0' back in front of the exponent.
223	        if (!value.includes('.') && value.includes('e')) {
224	          value = value.replace('e', '.0e');
225	        }
226	      }
227	      return this.representScalar('tag:yaml.org,2002:float', value);
228	    }
229	
230	    representList(data) {
231	      return this.representSequence('tag:yaml.org,2002:seq', data);
232	    }
233	
234	    representDict(data) {
235	      return this.representMapping('tag:yaml.org,2002:map', data);
236	    }
237	
238	    representSet(data) {
239	      const value = new PyDict();
240	      for (const key of data.values()) value.set(key, null);
241	      return this.representMapping('tag:yaml.org,2002:set', value);
242	    }
243	
244	    representDate(data) {
245	      const value = data.isoformat();
246	      return this.representScalar('tag:yaml.org,2002:timestamp', value);
247	    }
248	
249	    representDateTime(data) {
250	      const value = data.isoformat(' ');
251	      return this.representScalar('tag:yaml.org,2002:timestamp', value);
252	    }
253	
254	    representUndefined(data) {
255	      throw new RepresenterError('cannot represent an object');
256	    }
257	
258	    // ----------------------------------------------------- full Representer
259	
260	    representTuple(data) {
261	      return this.representSequence('tag:yaml.org,2002:python/tuple', data);
262	    }
263	
264	    // Stands in for PyYAML's copyreg-driven represent_object, registered as the
265	    // `object` multi-representer. Nothing safe_load can produce reaches it, and
266	    // an arbitrary reduce protocol has no JS analogue, so it raises the same
267	    // error represent_undefined would.
268	    representObject(data) {
269	      throw new RepresenterError('cannot represent an object');
270	    }
271	  }
272	
273	  Representer.prototype.yamlRepresenters = yamlRepresenters;
274	  Representer.prototype.yamlMultiRepresenters = yamlMultiRepresenters;
275	  return Representer;
276	};
277	
278	// SafeRepresenter.add_representer(...) block, in source order.
279	addRepresenter('NoneType', (self, data) => self.representNone(data));
280	addRepresenter('str', (self, data) => self.representStr(data));
281	addRepresenter('bytes', (self, data) => self.representBinary(data));
282	addRepresenter('bool', (self, data) => self.representBool(data));
283	addRepresenter('int', (self, data) => self.representInt(data));
284	addRepresenter('float', (self, data) => self.representFloat(data));
285	addRepresenter('list', (self, data) => self.representList(data));
286	addRepresenter('tuple', (self, data) => self.representList(data));
287	addRepresenter('dict', (self, data) => self.representDict(data));
288	addRepresenter('set', (self, data) => self.representSet(data));
289	addRepresenter('date', (self, data) => self.representDate(data));
290	addRepresenter('datetime', (self, data) => self.representDateTime(data));
291	addRepresenter(null, (self, data) => self.representUndefined(data));
292	
293	// Representer.add_representer(...) block — the full Dumper's overrides. The
294	// complex / name / module / OrderedDict entries have no reachable counterpart
295	// here (safe_load cannot build those values) and are omitted.
296	addRepresenter('tuple', (self, data) => self.representTuple(data));
297	addMultiRepresenter('object', (self, data) => self.representObject(data));
298
